```python
import random, time
from typing import Callable, TypeVar

T = TypeVar("T")

def retry(fn: Callable[[], T], attempts: int = 5, base: float = 0.5,
          cap: float = 30.0, on: tuple[type[Exception], ...] = (Exception,)) -> T:
    """Call fn, retrying on the given exceptions with full-jitter exponential backoff."""
    if attempts < 1:
        raise ValueError("attempts must be >= 1")
    for i in range(attempts):
        try:
            return fn()
        except on:
            if i == attempts - 1:
                raise
            time.sleep(random.uniform(0, min(cap, base * 2 ** i)))
    raise AssertionError("unreachable")
```

Full jitter (a uniform draw from 0 to delay) rather than delay times a random factor keeps a thundering herd from re-syncing. The last attempt re-raises with the traceback intact, and the exception types are a parameter so you do not swallow programming errors like TypeError along with transient ones.

```python
import json, urllib.request

class PayloadError(ValueError):
    pass

def fetch_json(url: str, *, timeout: float = 10.0, max_bytes: int = 2 * 1024 * 1024) -> dict:
    req = urllib.request.Request(url, headers={"User-Agent": "myapp/1.0"})
    with urllib.request.urlopen(req, timeout=timeout) as resp:
        if resp.status != 200:
            raise PayloadError(f"HTTP {resp.status}")
        raw = resp.read(max_bytes + 1)
        charset = resp.headers.get_content_charset() or "utf-8"
    if len(raw) > max_bytes:
        raise PayloadError("response too large")
    try:
        data = json.loads(raw.decode(charset))
    except (UnicodeDecodeError, json.JSONDecodeError) as exc:
        raise PayloadError(f"invalid JSON: {exc}") from exc
    if not isinstance(data, dict):
        raise PayloadError("expected a JSON object")
    return data
```

Four things matter: a timeout so a hung socket cannot block forever, a hard byte cap read with max_bytes + 1 so you detect oversize instead of silently truncating, decoding with the server's declared charset instead of assuming UTF-8, and a shape check so callers get a dict or a clear error rather than an occasional list.

