import { z } from "zod";

const Body = z.object({
  productId: z.string().min(1),
  quantity: z.number().int().positive().max(99),
});

export async function POST(req: Request) {
  let raw: unknown;
  try {
    raw = await req.json();
  } catch {
    return NextResponse.json({ error: "invalid JSON" }, { status: 400 });
  }

  const parsed = Body.safeParse(raw);
  if (!parsed.success) {
    return NextResponse.json(
      { error: "validation failed", issues: parsed.error.issues },
      { status: 422 }
    );
  }

  const { productId, quantity } = parsed.data;
  const order = await createOrder(productId, quantity);
  return NextResponse.json(order, { status: 201 });
}
```

Treat req.json() as unknown and narrow it with a schema, because the body is attacker-controlled and a type assertion is a lie at runtime. Return 400 for malformed JSON and 422 for a well-formed body that fails validation, so client error handling stays unambiguous. Route handlers must return a Response, so use NextResponse.json rather than a bare object.

