// Bug: count is captured from the first render, so the interval always logs 0.
function Bad() {
  const [count, setCount] = useState(0);
  useEffect(() => {
    const id = setInterval(() => console.log(count), 1000);
    return () => clearInterval(id);
  }, []); // empty deps -> closure over the first count
}

// Fix 1: functional update, no dependency on the captured value.
function Good() {
  const [count, setCount] = useState(0);
  useEffect(() => {
    const id = setInterval(() => setCount((c) => c + 1), 1000);
    return () => clearInterval(id);
  }, []);
}

// Fix 2: a ref when you need the latest value in a long-lived callback.
function GoodRef() {
  const [count, setCount] = useState(0);
  const latest = useRef(count);
  latest.current = count;
  useEffect(() => {
    const id = setInterval(() => console.log(latest.current), 1000);
    return () => clearInterval(id);
  }, []);
}
```

A closure captures the binding from the render it was created in. An empty dependency array means the effect never re-runs, so it keeps the first render's value forever. Prefer setState with an updater because it needs no dependency at all. Reach for a ref only when you genuinely need the newest value from a long-lived callback.

```tsx
import { useEffect, useState } from "react";

export function useSearch(query: string, delay = 300) {
  const [results, setResults] = useState<string[]>([]);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    if (!query.trim()) {
      setResults([]);
      return;
    }
    const controller = new AbortController();
    const timer = setTimeout(async () => {
      try {
        const url = "/api/search?q=" + encodeURIComponent(query);
        const res = await fetch(url, { signal: controller.signal });
        if (!res.ok) throw new Error("HTTP " + res.status);
        setResults(await res.json());
        setError(null);
      } catch (e) {
        if ((e as Error).name !== "AbortError") setError((e as Error).message);
      }
    }, delay);

    return () => {
      clearTimeout(timer);
      controller.abort();
    };
  }, [query, delay]);

  return { results, error };
}
```

Both cleanups matter. clearTimeout stops a request that has not fired yet, abort cancels one already in flight. Without the abort a slow early response can land after a fast later one and overwrite the list with results for an old query. Ignoring AbortError keeps cancellation out of your error state.

