use std::fs;
use std::path::Path;
use thiserror::Error;

#[derive(Debug, Error)]
pub enum ConfigError {
    #[error("cannot read {path}: {source}")]
    Io { path: String, #[source] source: std::io::Error },
    #[error("invalid config at line {line}: {message}")]
    Parse { line: usize, message: String },
}

pub fn load_config(path: impl AsRef<Path>) -> Result<String, ConfigError> {
    let path = path.as_ref();
    let text = fs::read_to_string(path).map_err(|source| ConfigError::Io {
        path: path.display().to_string(),
        source,
    })?;
    if text.trim().is_empty() {
        return Err(ConfigError::Parse { line: 1, message: "file is empty".into() });
    }
    Ok(text)
}
```

Use thiserror for library errors and anyhow for applications. The #[source] attribute keeps the io::Error so the cause chain survives, and display().to_string() captures the path because the io::Error does not know which file it came from. Returning Result instead of panicking lets the caller decide whether an unreadable config is fatal.

