use tokio::time::{timeout, Duration};

async fn fetch(url: &str) -> Result<String, Box<dyn std::error::Error + Send + Sync>> {
    let res = reqwest::get(url).await?;
    let res = res.error_for_status()?;
    Ok(res.text().await?)
}

#[tokio::main]
async fn main() -> Result<(), Box<dyn std::error::Error>> {
    // ? works in an async fn exactly as in a sync fn.
    let body = fetch("https://example.com").await?;

    // timeout wraps the future: Result<Result<T, E>, Elapsed>.
    let body = match timeout(Duration::from_secs(5), fetch("https://example.com")).await {
        Ok(Ok(b)) => b,
        Ok(Err(e)) => return Err(format!("fetch failed: {e}").into()),
        Err(_) => return Err("request timed out".into()),
    };

    // Run several concurrently instead of failing on the first.
    let results = futures::future::join_all(
        ["https://a.example", "https://b.example"].map(fetch)
    ).await;
    for r in results { let _ = r?; }

    println!("{}", body.len());
    Ok(())
}
```

The ? operator propagates within any function returning Result, including async ones. Box<dyn Error + Send + Sync> is the pragmatic return type when callers do not need to match on variants; a concrete thiserror enum is better in a library. timeout returns a nested Result, which is why the match nests.

