use std::collections::HashMap;
use std::sync::Arc;
use tokio::sync::RwLock;

type Store = Arc<RwLock<HashMap<String, u64>>>;

#[derive(Clone)]
struct App { store: Store }

impl App {
    fn new() -> Self { Self { store: Arc::new(RwLock::new(HashMap::new())) } }

    async fn incr(&self, key: &str) -> u64 {
        let mut map = self.store.write().await;
        let counter = map.entry(key.to_string()).or_insert(0);
        *counter += 1;
        *counter
    }

    async fn get(&self, key: &str) -> Option<u64> {
        self.store.read().await.get(key).copied()
    }
}

#[tokio::main]
async fn main() {
    let app = App::new();
    let mut handles = Vec::new();
    for i in 0..8 {
        let app = app.clone(); // cheap: only the Arc is cloned
        handles.push(tokio::spawn(async move { app.incr(&format!("k{i}")).await; }));
    }
    for h in handles { h.await.unwrap(); }
    println!("{:?}", app.get("k0").await);
}
```

Use tokio::sync::RwLock, not std::sync::Mutex, because holding a std lock across an await point blocks the executor thread and can deadlock. Arc makes cloning the handle cheap so each task gets its own reference. Keep the write lock scope short and never hold it across another await.

