// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

import {ReentrancyGuard} from "@openzeppelin/contracts/utils/ReentrancyGuard.sol";

contract Vault is ReentrancyGuard {
    mapping(address => uint256) public balances;

    error InsufficientBalance();
    error TransferFailed();

    function withdraw(uint256 amount) external nonReentrant {
        uint256 balance = balances[msg.sender];
        if (balance < amount) revert InsufficientBalance();

        // Checks-Effects-Interactions: zero the balance before the external call.
        balances[msg.sender] = balance - amount;

        (bool ok,) = msg.sender.call{value: amount}("");
        if (!ok) revert TransferFailed();
    }
}
```

Two independent defences. Checks-Effects-Interactions updates state before the external call, so a reentrant call sees a zero balance. nonReentrant is a mutex that reverts on re-entry. Always check the return value of call; a bare call that ignores the bool is how "the withdrawal silently failed" bugs ship. Solidity 0.8 has built-in overflow checks, so balance - amount cannot underflow once the guard is in place.

