import Foundation

enum FetchError: Error { case cancelled, badStatus(Int) }

func fetchProfile(id: String) async throws -> Data {
    let url = URL(string: "https://api.example.com/profiles/\(id)")!
    var request = URLRequest(url: url)
    request.timeoutInterval = 10

    let (data, response) = try await URLSession.shared.data(for: request)

    // Cooperative cancellation: check before doing more work.
    try Task.checkCancellation()

    guard let http = response as? HTTPURLResponse, (200..<300).contains(http.statusCode) else {
        throw FetchError.badStatus((response as? HTTPURLResponse)?.statusCode ?? -1)
    }
    return data
}

let task = Task { try await fetchProfile(id: "42") }
task.cancel() // URLSession observes this and throws CancellationError
```

Swift concurrency cancellation is cooperative, nothing is killed for you. Task.checkCancellation() throws at a point you choose, which keeps the cancelled branch inside your own error type. URLSession's async methods already observe task cancellation, so the await throws CancellationError. Never swallow that with a bare catch; either rethrow or map it to your cancelled case.

