import SwiftUI

@MainActor
final class ProfileStore: ObservableObject {
    enum State { case idle, loading, loaded([Profile]), failed(String) }
    @Published private(set) var state: State = .idle
    @Published var query = ""

    func load() async {
        state = .loading
        do {
            var components = URLComponents(string: "https://api.example.com/profiles")!
            if !query.isEmpty { components.queryItems = [.init(name: "q", value: query)] }
            let (data, _) = try await URLSession.shared.data(from: components.url!)
            state = .loaded(try JSONDecoder().decode([Profile].self, from: data))
        } catch {
            state = .failed(error.localizedDescription)
        }
    }
}

struct ProfileList: View {
    @StateObject private var store = ProfileStore()

    var body: some View {
        NavigationStack {
            Group {
                switch store.state {
                case .idle, .loading:
                    ProgressView()
                case .failed(let message):
                    ContentUnavailableView("Could not load", systemImage: "wifi.slash",
                                           description: Text(message))
                case .loaded(let profiles):
                    List(profiles) { p in Text(p.name) }
                }
            }
            .navigationTitle("Profiles")
            .searchable(text: $store.query)
            .task(id: store.query) { await store.load() }
        }
    }
}
```

Model the states as an enum so loading, empty and failed are exhaustive and impossible to mix up, instead of a pile of booleans. @MainActor on the store means every Published mutation happens on the main thread with no manual dispatch. .task(id:) cancels and restarts the work when the query changes, which gives search-as-you-type without an explicit debounce.

