import kotlinx.coroutines.*

class ProfileRepository(private val api: Api) {

    // Fail-fast: if either fails, the sibling is cancelled.
    suspend fun loadDashboard(userId: String): Dashboard = coroutineScope {
        val profile = async { api.profile(userId) }
        val feed = async { api.feed(userId) }
        Dashboard(profile.await(), feed.await())
    }

    // Isolated failures for optional parts of the page.
    suspend fun loadOptionalDashboard(userId: String): Dashboard = supervisorScope {
        val profile = async { api.profile(userId) }
        val feed = async { runCatching { api.feed(userId) }.getOrElse { emptyList() } }
        Dashboard(profile.await(), feed.await())
    }
}
```

coroutineScope is fail-fast and cancels the sibling, which is what you want when both results are required. supervisorScope isolates failures so a broken optional feed does not take down the page. Never use GlobalScope here: it escapes structured concurrency and leaks work past the caller's lifetime. Do not switch to Dispatchers.IO inside a suspend function that is already suspend; the library moves the work for you.

